window.CODE_SNIPPETS = {"crawler": {"name": "crawler.py", "lines": 299, "src": "# -*- coding: utf-8 -*-\n\"\"\"\ncrawler.py —— 大众点评北京餐厅采集（成员1，新手简化版）\n========================================================\n\n【这个脚本干什么】\n    访问大众点评的餐厅列表页，把网页原文保存到本地，交给成员2 去解析。\n\n【怎么用】\n    第 1 步：把浏览器里的 Cookie 存到 cookie.txt（和本文件放同一个文件夹）\n    第 2 步：直接运行  python crawler.py\n    第 3 步：看最后打印的结果\n\n【为什么需要 Cookie】\n    不带 Cookie 去访问，大众点评会把你跳到\"验证中心\"页面，\n    什么都抓不到。所以我从浏览器复制了登录后的 Cookie 带上。\n\n【这个脚本总共就 4 步】\n    1. 读取配置和 Cookie\n    2. 循环抓 10 页\n    3. 每页判断：是正常页面还是被风控拦了\n    4. 正常就存文件，被拦就停下来\n\n【说明】\n    全程只用了 Python 自带的工具，不需要 pip 安装任何东西。\n\"\"\"\n\n# ==============================================================================\n# 第 1 部分：导入工具\n# ==============================================================================\nimport json                 # 用来保存\"采集记录\"文件\nimport random               # 用来生成随机等待时间\nimport re                   # 正则表达式，用来在网页里找店名、找数字\nimport time                 # 用来 sleep（等待）\nimport urllib.request       # Python 自带的\"浏览器\"，用它去访问网址\nfrom datetime import datetime\nfrom pathlib import Path    # 用来处理文件路径\n\n\n# ==============================================================================\n# 第 2 部分：配置（想改参数就改这里，不用动下面的代码）\n# ==============================================================================\n\n# 要抓的网址。ch10 是\"美食\"分类，beijing 是北京。\nSTART_URL = \"https://www.dianping.com/beijing/ch10\"\n\n# 抓几页。想先试试就改成 1。\nPAGES = 10\n\n# 每抓一页休息几秒。这个不能省！请求太快会被网站封 IP。\n# 用随机数是因为固定间隔太规律，容易被识别成程序。\nWAIT_MIN = 2\nWAIT_MAX = 5\n\n# Cookie 存放的位置（和本脚本同一个文件夹）\nCOOKIE_FILE = Path(__file__).parent / \"cookie.txt\"\n\n# 网页保存到哪里\nOUT_DIR = Path(__file__).parent / \"raw\"\n\n\n# ==============================================================================\n# 第 3 部分：小工具函数\n# ==============================================================================\n\ndef read_cookie():\n    \"\"\"读取 cookie.txt 里的 Cookie 内容。\"\"\"\n    if not COOKIE_FILE.exists():\n        print(\"错误：找不到 cookie.txt\")\n        print(\"请把浏览器里的 Cookie 存成 cookie.txt，和本脚本放在同一个文件夹。\")\n        return \"\"\n\n    # encoding=\"utf-8-sig\" 会自动去掉文件开头的隐藏字符（BOM）。\n    # 这个隐藏字符会让网络请求报错，所以必须去掉。\n    cookie = COOKIE_FILE.read_text(encoding=\"utf-8-sig\").strip()\n    print(\"已读取 Cookie，长度 \" + str(len(cookie)) + \" 个字符\")\n    return cookie\n\n\ndef build_page_url(page):\n    \"\"\"\n    拼出第 N 页的网址。\n    第 1 页是  .../ch10\n    第 2 页是  .../ch10/p2\n    第 3 页是  .../ch10/p3\n    \"\"\"\n    if page == 1:\n        return START_URL\n    return START_URL + \"/p\" + str(page)\n\n\ndef fetch(url, cookie):\n    \"\"\"\n    访问一个网址，把网页内容取回来。\n\n    返回网页文字；如果出错了就返回空字符串。\n    \"\"\"\n    # 告诉服务器\"我是正常浏览器\"。不加这个会被当成爬虫直接拒绝。\n    headers = {\n        \"User-Agent\": (\n            \"Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 \"\n            \"(KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36\"\n        ),\n        \"Accept\": \"text/html,application/xhtml+xml,application/xml;q=0.9\",\n        \"Accept-Language\": \"zh-CN,zh;q=0.9\",\n        \"Cookie\": cookie,\n    }\n\n    try:\n        # 把网址和请求头打包成一个\"请求\"\n        request = urllib.request.Request(url, headers=headers)\n        # 打开这个请求，读取内容\n        with urllib.request.urlopen(request, timeout=20) as response:\n            html = response.read().decode(\"utf-8\", errors=\"replace\")\n            return html\n    except Exception as error:\n        # 网络出错（比如超时、断网）不让程序崩掉，打印一下继续\n        print(\"  请求失败：\" + type(error).__name__ + \" - \" + str(error))\n        return \"\"\n\n\ndef is_blocked(html):\n    \"\"\"\n    判断这一页是不是被风控拦了（跳到了验证页面）。\n\n    返回 True 表示被拦了。\n\n    判断方法有两个：\n      1. 页面里出现\"验证\"\"captcha\"\"yoda\"这些词 —— yoda 是美团风控系统的名字\n      2. 页面特别小 —— 正常列表页有 20 万字符，验证页只有几千\n    \"\"\"\n    if len(html) < 5000:\n        return True\n\n    keywords = [\"verify\", \"captcha\", \"yoda\", \"滑动验证\", \"安全验证\", \"访问过于频繁\"]\n    for word in keywords:\n        if word in html.lower():\n            return True\n\n    return False\n\n\ndef have_font_encryption(html):\n    \"\"\"\n    判断页面有没有\"字体加密\"。\n\n    大众点评以前会把店名弄成乱码（长这样：&#xe1a3;），\n    那样就必须先解密才能读出店名。\n\n    返回 True 表示有加密。\n    \"\"\"\n    # 找所有 &#x....; 这种形式的乱码\n    found = re.findall(r\"&#x[0-9a-fA-F]{3,5};\", html)\n    return len(found) > 0\n\n\ndef count_shops(html):\n    \"\"\"数一数这一页有几家店（每家店都有一个 data-shopid 编号）。\"\"\"\n    ids = re.findall(r'data-shopid=\"([A-Za-z0-9]+)\"', html)\n    # set() 是用来去重的，同一家店可能出现多次\n    return len(set(ids))\n\n\ndef save_page(html, page, date_dir):\n    \"\"\"\n    把网页保存成文件。\n\n    保存位置长这样：raw/2026-10-15/page01/index.html\n    为什么要分两层文件夹？\n      · 日期文件夹：每次采集单独放一个，不会互相覆盖\n      · page01 文件夹：一页一个，以后字体文件、记录文件都能放进去\n    这样成员2 的 parser.py 才能按固定路径找到文件。\n    \"\"\"\n    page_dir = date_dir / (\"page\" + str(page).zfill(2))\n    page_dir.mkdir(parents=True, exist_ok=True)      # 文件夹不存在就创建\n    file_path = page_dir / \"index.html\"\n    file_path.write_text(html, encoding=\"utf-8\")\n    return file_path\n\n\n# ==============================================================================\n# 第 4 部分：主流程\n# ==============================================================================\n\ndef main():\n    print(\"=\" * 60)\n    print(\"大众点评餐厅采集（成员1）\")\n    print(\"=\" * 60)\n\n    # 4.1 读取 Cookie\n    cookie = read_cookie()\n    if not cookie:\n        return\n\n    print(\"目标网址：\" + START_URL)\n    print(\"计划抓取：\" + str(PAGES) + \" 页\")\n    print(\"每页间隔：\" + str(WAIT_MIN) + \"~\" + str(WAIT_MAX) + \" 秒\")\n\n    # 今天日期，用来建文件夹（比如 raw/2026-10-15）\n    today = datetime.now().strftime(\"%Y-%m-%d\")\n    date_dir = OUT_DIR / today\n    date_dir.mkdir(parents=True, exist_ok=True)\n    print(\"保存到  ：\" + str(date_dir))\n    print(\"-\" * 60)\n\n    # 4.2 准备一个列表，记录每一页的情况\n    records = []\n    success = 0        # 成功页数\n    total_shops = 0    # 累计门店数\n\n    # 4.3 一页一页地抓\n    for page in range(1, PAGES + 1):\n\n        # 第一页不用等，后面的页要等一会儿（限速）\n        if page > 1:\n            wait = random.uniform(WAIT_MIN, WAIT_MAX)\n            time.sleep(wait)\n\n        url = build_page_url(page)\n        print(\"第 \" + str(page) + \" 页：\" + url)\n\n        html = fetch(url, cookie)\n\n        # 请求失败，跳过这一页\n        if not html:\n            records.append({\"page\": page, \"url\": url, \"ok\": False, \"status\": \"请求失败\"})\n            continue\n\n        # 判断是不是被风控拦了\n        if is_blocked(html):\n            print(\"  被风控拦截了，停止采集\")\n            records.append({\"page\": page, \"url\": url, \"ok\": False, \"status\": \"被风控拦截\"})\n            break       # 遇到拦截就立刻停，不要硬撑着继续抓，不然 IP 会被封\n\n        # 保存文件\n        file_path = save_page(html, page, date_dir)\n\n        # 统计这一页的情况\n        shop_count = count_shops(html)\n        encrypted = have_font_encryption(html)\n        success = success + 1\n        total_shops = total_shops + shop_count\n\n        print(\"  保存成功：\" + file_path.name\n              + \"，大小 \" + str(len(html)) + \" 字符\"\n              + \"，门店 \" + str(shop_count) + \" 家\")\n\n        records.append({\n            \"page\": page,\n            \"url\": url,\n            \"ok\": True,\n            \"html_size\": len(html),\n            \"shop_count\": shop_count,\n            \"font_encrypted\": encrypted,        # 有没有字体加密\n            \"saved_to\": file_path.name,\n        })\n\n    # 4.4 保存一份采集记录\n    date_dir.mkdir(parents=True, exist_ok=True)\n    record_file = date_dir / \"record.json\"\n    record_file.write_text(\n        json.dumps({\n            \"采集时间\": datetime.now().strftime(\"%Y-%m-%d %H:%M:%S\"),\n            \"成功页数\": success,\n            \"门店总数\": total_shops,\n            \"每页记录\": records,\n        }, ensure_ascii=False, indent=2),\n        encoding=\"utf-8\",\n    )\n\n    # 4.5 打印总结\n    print(\"-\" * 60)\n    print(\"采集完成\")\n    print(\"=\" * 60)\n    print(\"  成功页数  ：\" + str(success) + \" / \" + str(PAGES))\n    print(\"  门店总数  ：\" + str(total_shops) + \" 家\")\n    print(\"  采集记录  ：\" + str(record_file))\n    print(\"-\" * 60)\n\n    # 得出结论：走哪条技术路线\n    if success == 0:\n        print(\"  结论：什么都没抓到。\")\n        print(\"  可能原因：Cookie 过期了，重新从浏览器复制一份。\")\n        print(\"            或者网络不通，先试试能不能打开 dianping.com。\")\n    else:\n        # 看最后一页有没有字体加密\n        encrypted_pages = [r for r in records if r.get(\"font_encrypted\")]\n        if encrypted_pages:\n            print(\"  结论：页面有字体加密！\")\n            print(\"  成员2 需要先写解密程序，把乱码还原成文字，才能解析。\")\n        else:\n            print(\"  结论：页面没有字体加密，店名都是明文。\")\n            print(\"  成员2 可以直接解析，不需要写解密程序。\")\n    print(\"=\" * 60)\n\n\n# 这一句的意思是：只有直接运行本文件时才执行 main()，被别人 import 时不执行\nif __name__ == \"__main__\":\n    main()\n"}, "parser": {"name": "parser.py", "lines": 420, "src": "# -*- coding: utf-8 -*-\n\"\"\"\nparser.py —— 原始 HTML 解析与清洗（成员2 交付物）\n================================================================================\n\n【一句话说明】\n    这个脚本负责项目的\"第二步\"：把成员1 采集到的原始 HTML，\n    解析成一张干净的数据表 data/restaurants_clean.csv，\n    交给成员3 去做加权建模和 Top100 排序。\n\n【它在流水线的位置】\n    成员1 采集 ──► 【成员2 解析】 ──► 成员3 建模 ──► 成员4 可视化\n    raw/*.html     restaurants_clean.csv     top100.csv     dashboard\n\n【输入输出】\n    输入：raw/<日期>/pageNN/index.html     （成员1 落盘的 10 个页面）\n    输出：data/restaurants_clean.csv       （150 家 × 6 字段，UTF-8-BOM，Excel 可直接打开）\n\n【⭐ 本脚本最重要的一个结论：不需要字体解密】\n    坑位说明：大众点评**曾经**把店名和评分渲染成私有字体的乱码（&#xe1a3; 这种形态），\n    那样就必须先建\"字形码位 → 真实字符\"的映射表才能还原文字。\n\n    但成员1 实测（2026-10-15）确认：**当前页面没有任何字体加密**，\n    店名是明文 <h4>、评分写在 CSS 类名里、评论数和人均是明文 <b>。\n    因此本项目**不需要 font_decode.py**，直接用下面的正则解析即可。\n    脚本里保留了一个 `--allow-font-entities` 开关，万一以后站点改回去，能立刻发现。\n\n【解析的 5 个坑（成员1 实测踩过，代码里都处理了）】\n    1. <h4> 不止 15 个 —— 筛选栏的「分类:」「地点:」也在 <h4> 里（每页多出 2 个）。\n       解法：只处理含 data-shopid 的块，卡片内部才认 <h4>。\n    2. 评分不是文本 —— 页面上根本找不到\"4.5分\"这种字，评分写在类名 star_45 里。\n       解法：正则取 star_ 后面的数字，再除以 10。\n    3. 评论数可能带千分位逗号（如 42,277）。\n       解法：正则保留数字和逗号，再统一 replace(\",\", \"\")。\n    4. 人均用全角 ￥（不是半角 ¥）。\n       解法：正则用 [￥¥] 两种都兼容。\n    5. 按 <div class=\"txt\"> 切分后，最后一块是页尾脏块。\n       解法：跳过没有 data-shopid 的块。\n\n【运行】\n    python parser.py                          # 默认读 raw/，写 data/restaurants_clean.csv\n    python parser.py --raw raw --out data/restaurants_clean.csv\n    python parser.py --raw raw/2026-10-15     # 只解析某一次采集\n\"\"\"\n\nfrom __future__ import annotations\n\nimport argparse\nimport csv\nimport json\nimport re\nimport sys\nfrom collections import Counter\nfrom datetime import datetime\nfrom pathlib import Path\n\n\n# ==============================================================================\n# 第 0 部分：控制台编码修复（⚠️ 中国区 Windows 必看）\n# ==============================================================================\ndef force_utf8_console() -> None:\n    \"\"\"\n    把程序输出强制切换成 UTF-8。\n\n    为什么需要这一步（踩过的真实坑）：\n        中文版 Windows 的 Python 控制台默认用 GBK 编码输出。\n        GBK 能显示中文，但**放不下** ✓ ✗ ► █ ← 这些符号，\n        一旦 print 它们，程序会直接崩溃并报：\n            UnicodeEncodeError: 'gbk' codec can't encode character '\\\\u2713'\n\n        本脚本的数据质量报告里正好用了这些符号，所以在别人的电脑上会一运行就报错。\n        这里在程序入口处把标准输出重设为 UTF-8，从根上解决。\n\n    为什么用 try 包起来：\n        如果输出被重定向成不支持 reconfigure 的对象（极少数环境），\n        不能让这个修复本身把程序搞崩，失败了就照常继续。\n    \"\"\"\n    for stream in (sys.stdout, sys.stderr):\n        try:\n            stream.reconfigure(encoding=\"utf-8\", errors=\"replace\")\n        except Exception:                      # noqa: BLE001 —— 修复失败也要继续跑\n            pass\n\n# ==============================================================================\n# 第 1 部分：解析规则（全部正则集中在这里，站点结构变了只需要改这一段）\n# ==============================================================================\n\n# 卡片切分：每张店铺卡片的正文都在 <div class=\"txt\"> 之后\nCARD_SPLIT_RE = re.compile(r'<div class=\"txt\">')\n\n# 判断一个块是不是真卡片：只有真卡片带 data-shopid\nSHOP_ID_RE = re.compile(r'data-shopid=\"([A-Za-z0-9]+)\"')\n\n# 店名：卡片内部的第一个 <h4>\nNAME_RE = re.compile(r\"<h4>(.*?)</h4>\", re.S)\n\n# 评分：类名 star_45 表示 4.5 分（坑 2）\nSTAR_RE = re.compile(r'class=\"star star_(\\d+)\\s')\n\n# 评论数：<b>42277</b> 条评价（坑 3：兼容千分位逗号）\nREVIEW_RE = re.compile(r\"<b>\\s*([\\d,]+)\\s*</b>\\s*条评价\", re.S)\n\n# 人均价格：人均 <b>￥103</b>（坑 4：全角/半角都兼容）\nPRICE_RE = re.compile(r\"人均\\s*<b>\\s*[￥¥]?\\s*([\\d,]+)\\s*</b>\", re.S)\n\n# 标签：品类和商圈都用 <span class=\"tag\"> 包裹（第 1 个是品类，第 2 个是商圈）\nTAG_RE = re.compile(r'<span class=\"tag\">(.*?)</span>', re.S)\n\n# 字体加密探针：私用区编码实体（&#xe1a3; 这种形态）\nFONT_ENTITY_RE = re.compile(r\"&#x([0-9a-fA-F]{3,5});\")\n\n# 输出 CSV 的字段顺序（成员3 的表结构按这个来）\nCSV_FIELDS = [\"shop_id\", \"name\", \"rating\", \"review_count\", \"avg_price\", \"category\", \"district\", \"source_page\"]\n\n\n# ==============================================================================\n# 第 2 部分：单页解析\n# ==============================================================================\n\ndef clean_text(raw: str | None) -> str | None:\n    \"\"\"\n    清洗文本：去掉 HTML 标签、压缩连续空白、去掉首尾空格。\n    为什么需要它：标签里可能夹着换行和缩进（例如 <span class=\"tag\">\\n  云南菜\\n</span>），\n    不清洗会得到带换行的脏值。\n    \"\"\"\n    if raw is None:\n        return None\n    text = re.sub(r\"<[^>]+>\", \"\", raw)      # 去掉残余 HTML 标签\n    text = re.sub(r\"\\s+\", \" \", text)        # 连续空白压成一个空格\n    text = text.strip()\n    return text or None                     # 空字符串统一返回 None，便于统计缺失\n\n\ndef to_int(raw: str | None) -> int | None:\n    \"\"\"把 '42,277' 这类文本转成整数 42277；转不了返回 None（不抛异常）。\"\"\"\n    if not raw:\n        return None\n    digits = re.sub(r\"[^\\d]\", \"\", raw)      # 只保留数字，顺手干掉千分位逗号\n    return int(digits) if digits else None\n\n\ndef parse_card(block: str, page: int) -> dict | None:\n    \"\"\"\n    解析一张店铺卡片，返回一条记录；不是真卡片则返回 None。\n    参数 page 会写进 source_page 字段，方便回溯数据来自哪一页。\n    \"\"\"\n    # 坑 1 + 坑 5：没有 data-shopid 的块直接跳过（筛选栏脏块、页尾空块）\n    sid_match = SHOP_ID_RE.search(block)\n    if not sid_match:\n        return None\n    name_match = NAME_RE.search(block)\n    if not name_match:\n        return None\n\n    # 评分：类名 star_45 -> 4.5。注意要用 float 再除，避免整数除法\n    star_match = STAR_RE.search(block)\n    rating = int(star_match.group(1)) / 10 if star_match else None\n\n    # 标签：第 1 个是品类，第 2 个是商圈\n    tags = [clean_text(t) for t in TAG_RE.findall(block)]\n    tags = [t for t in tags if t]           # 过滤掉空标签\n    category = tags[0] if len(tags) >= 1 else None\n    district = tags[1] if len(tags) >= 2 else None\n\n    return {\n        \"shop_id\": sid_match.group(1),\n        \"name\": clean_text(name_match.group(1)),\n        \"rating\": rating,\n        \"review_count\": to_int(REVIEW_RE.search(block).group(1)) if REVIEW_RE.search(block) else None,\n        \"avg_price\": to_int(PRICE_RE.search(block).group(1)) if PRICE_RE.search(block) else None,\n        \"category\": category,\n        \"district\": district,\n        \"source_page\": page,\n    }\n\n\ndef parse_page(html: str, page: int) -> tuple[list[dict], int]:\n    \"\"\"\n    解析一页 HTML，返回 (记录列表, 字体加密实体数量)。\n    那个实体数量是给成员1 的字体加密结论做交叉验证用的：\n    它应该恒为 0，如果不是 0 就说明站点改回字体加密了。\n    \"\"\"\n    records: list[dict] = []\n    for block in CARD_SPLIT_RE.split(html)[1:]:     # [1:] 跳过第一个切分前的头部\n        rec = parse_card(block, page)\n        if rec:\n            records.append(rec)\n    return records, len(FONT_ENTITY_RE.findall(html))\n\n\n# ==============================================================================\n# 第 3 部分：读取 raw/ 目录\n# ==============================================================================\n\ndef collect_pages(raw_dir: Path) -> list[tuple[int, Path]]:\n    \"\"\"\n    找出所有待解析的页面文件，返回 [(页码, 文件路径), ...] 并按页码排序。\n\n    支持两种传参：\n      · 传 raw/          —— 自动挑**最新日期**的目录（如 raw/2026-10-15）\n      · 传 raw/2026-10-15 —— 直接解析指定目录\n    这样成员1 重跑采集后，不用改命令就能解析到最新数据。\n    \"\"\"\n    if not raw_dir.exists():\n        return []\n\n    # 如果目录里直接就有 pageNN 子目录，说明传的是日期目录本身\n    if list(raw_dir.glob(\"page*/index.html\")):\n        base = raw_dir\n    else:\n        # 否则在子目录里找最新的日期目录\n        dated = sorted([d for d in raw_dir.iterdir() if d.is_dir() and list(d.glob(\"page*/index.html\"))])\n        if not dated:\n            return []\n        base = dated[-1]                        # 名字是日期格式，排序后最后一个就是最新\n        print(f\"[提示] 自动选用最新采集目录：{base}\")\n\n    pages: list[tuple[int, Path]] = []\n    for p in base.glob(\"page*/index.html\"):\n        m = re.search(r\"page(\\d+)\", p.parent.name)\n        if m:\n            pages.append((int(m.group(1)), p))\n    return sorted(pages)\n\n\n# ==============================================================================\n# 第 4 部分：清洗与去重\n# ==============================================================================\n\ndef dedupe(records: list[dict]) -> tuple[list[dict], int]:\n    \"\"\"\n    按 shop_id 去重。同一家店可能因为列表刷新出现在两页里。\n    保留**第一次出现**的那条（页码更靠前 = 平台排序更靠前）。\n    返回 (去重后列表, 被剔除的重复条数)。\n    \"\"\"\n    seen: set[str] = set()\n    result: list[dict] = []\n    for rec in records:\n        sid = rec.get(\"shop_id\")\n        if not sid or sid in seen:\n            continue\n        seen.add(sid)\n        result.append(rec)\n    return result, len(records) - len(result)\n\n\n# ==============================================================================\n# 第 5 部分：写出 CSV\n# ==============================================================================\n\ndef write_csv(records: list[dict], out_path: Path) -> None:\n    \"\"\"\n    写 CSV 文件。\n    两个细节：\n      · newline=\"\"      —— csv 模块的要求，否则 Windows 上会多出空行\n      · utf-8-sig       —— 带 BOM，双击用 Excel 打开时中文不乱码\n    \"\"\"\n    out_path.parent.mkdir(parents=True, exist_ok=True)\n    with out_path.open(\"w\", newline=\"\", encoding=\"utf-8-sig\") as f:\n        writer = csv.DictWriter(f, fieldnames=CSV_FIELDS)\n        writer.writeheader()\n        writer.writerows(records)\n\n\n# ==============================================================================\n# 第 6 部分：数据质量报告（这是给全组看的\"体检表\"）\n# ==============================================================================\n\ndef print_quality_report(records: list[dict], total_raw: int, dup: int, font_entities: int) -> None:\n    \"\"\"打印数据质量统计：条数、字段完整率、取值范围、分布。\"\"\"\n    print(\"\\n\" + \"=\" * 68)\n    print(\"  数据质量报告\")\n    print(\"=\" * 68)\n    print(f\"  解析原始条数    : {total_raw}\")\n    print(f\"  去重剔除        : {dup} 条（同一门店重复出现）\")\n    print(f\"  最终门店数      : {len(records)}\")\n    print(f\"  字体加密实体    : {font_entities} 个{'  ← 应为 0，非 0 说明站点改回字体加密了' if font_entities else '  ✓ 已确认无字体加密'}\")\n\n    if not records:\n        print(\"  ✗ 没有解析到任何数据，请检查 raw/ 目录\")\n        print(\"=\" * 68 + \"\\n\")\n        return\n\n    # 6.1 字段完整率\n    print(\"-\" * 68)\n    print(\"  字段完整率：\")\n    for field in CSV_FIELDS:\n        if field == \"source_page\":\n            continue\n        filled = sum(1 for r in records if r.get(field) not in (None, \"\"))\n        rate = filled / len(records) * 100\n        flag = \"✓\" if rate == 100 else (\"!\" if rate >= 95 else \"✗\")\n        print(f\"    {flag} {field:15s} {filled:4d}/{len(records)}  ({rate:5.1f}%)\")\n\n    # 6.2 取值范围\n    def span(field: str) -> tuple:\n        vals = [r[field] for r in records if r.get(field) is not None]\n        return (min(vals), max(vals)) if vals else (None, None)\n\n    r_lo, r_hi = span(\"rating\")\n    c_lo, c_hi = span(\"review_count\")\n    p_lo, p_hi = span(\"avg_price\")\n    print(\"-\" * 68)\n    print(\"  取值范围：\")\n    print(f\"    评分      : {r_lo} ~ {r_hi}\")\n    print(f\"    评论数    : {c_lo} ~ {c_hi}\")\n    print(f\"    人均      : ￥{p_lo} ~ ￥{p_hi}\")\n\n    # 6.3 评分分布 —— 这一项直接影响成员3 的权重设计，值得单独看\n    print(\"-\" * 68)\n    print(\"  评分分布（注意集中度，会影响归一化效果）：\")\n    rating_counter = Counter(r[\"rating\"] for r in records if r.get(\"rating\") is not None)\n    for score in sorted(rating_counter, reverse=True):\n        n = rating_counter[score]\n        bar = \"█\" * round(n / len(records) * 40)\n        print(f\"    {score:<4} {n:4d} 家  {bar}\")\n\n    # 6.4 品类 / 商圈 TOP5\n    print(\"-\" * 68)\n    print(\"  品类 TOP5 :\", \"、\".join(f\"{k}({v})\" for k, v in Counter(r[\"category\"] for r in records).most_common(5)))\n    print(\"  商圈 TOP5 :\", \"、\".join(f\"{k}({v})\" for k, v in Counter(r[\"district\"] for r in records).most_common(5)))\n\n    # 6.5 门槛检查：提醒成员3 的 min_threshold 是否真的起作用\n    below = [r for r in records if (r.get(\"review_count\") or 0) < 100]\n    print(\"-\" * 68)\n    print(f\"  评论数 < 100 的门店: {len(below)} 家\"\n          + (\"  ← 门槛 min_threshold=100 不起筛选作用，建议 P4 定榜前重新确认\"\n             if not below else \"  ← 门槛会过滤掉这些低评论噪声店\"))\n    print(\"=\" * 68 + \"\\n\")\n\n\n# ==============================================================================\n# 第 7 部分：命令行参数与主流程\n# ==============================================================================\n\ndef parse_args(argv: list[str] | None = None) -> argparse.Namespace:\n    parser = argparse.ArgumentParser(\n        description=\"解析大众点评原始 HTML，产出干净 CSV（成员2）\",\n        formatter_class=argparse.RawDescriptionHelpFormatter,\n        epilog=(\n            \"示例：\\n\"\n            \"  python parser.py\\n\"\n            \"  python parser.py --raw raw/2026-10-15\\n\"\n            \"  python parser.py --out data/restaurants_clean.csv\\n\"\n        ),\n    )\n    parser.add_argument(\"--raw\", default=\"raw\", help=\"原始 HTML 目录（默认 raw/，自动取最新日期）\")\n    parser.add_argument(\"--out\", default=\"data/restaurants_clean.csv\", help=\"输出 CSV 路径\")\n    parser.add_argument(\"--json\", default=\"\", help=\"可选：额外输出一份 JSON（给成员4 调试用）\")\n    parser.add_argument(\"--allow-font-entities\", action=\"store_true\",\n                        help=\"允许页面存在字体加密实体（默认不允许，发现就报错提醒）\")\n    return parser.parse_args(argv)\n\n\ndef main(argv: list[str] | None = None) -> int:\n    args = parse_args(argv)\n    raw_dir = Path(args.raw)\n    out_path = Path(args.out)\n\n    print(\"=\" * 68)\n    print(\"  大众点评数据解析（成员2）\")\n    print(\"=\" * 68)\n    print(f\"  输入目录 : {raw_dir}\")\n    print(f\"  输出文件 : {out_path}\")\n\n    # 7.1 找页面\n    pages = collect_pages(raw_dir)\n    if not pages:\n        print(f\"\\n  ✗ 在 {raw_dir} 里没找到 page*/index.html\")\n        print(\"    请先运行采集：python crawler.py --pages 10 --cookie-file cookie.txt\")\n        return 2\n    print(f\"  待解析   : {len(pages)} 页（第 {pages[0][0]} 页 ~ 第 {pages[-1][0]} 页）\")\n\n    # 7.2 逐页解析\n    all_records: list[dict] = []\n    total_font_entities = 0\n    for page_no, path in pages:\n        html = path.read_text(encoding=\"utf-8\")\n        records, entities = parse_page(html, page_no)\n        all_records.extend(records)\n        total_font_entities += entities\n        print(f\"    第 {page_no:02d} 页 -> {len(records)} 家门店\")\n\n    # 7.3 字体加密检查：这是成员1 的结论，这里做交叉验证\n    if total_font_entities > 0 and not args.allow_font_entities:\n        print(f\"\\n  ✗ 检测到 {total_font_entities} 个字体加密实体（&#x....;）\")\n        print(\"    说明站点重新启用了字体加密，当前解析结果会是乱码。\")\n        print(\"    请启用 font_decode.py 建立映射表后再解析；\")\n        print(\"    如确认要强行解析，加 --allow-font-entities 参数。\")\n        return 3\n\n    # 7.4 去重 + 写文件\n    records, dup = dedupe(all_records)\n    write_csv(records, out_path)\n    print(f\"\\n  已写出 : {out_path}（{len(records)} 条）\")\n\n    # 7.5 可选 JSON 输出\n    if args.json:\n        Path(args.json).write_text(\n            json.dumps({\"generated_at\": datetime.now().isoformat(timespec=\"seconds\"),\n                        \"count\": len(records), \"items\": records},\n                       ensure_ascii=False, indent=2),\n            encoding=\"utf-8\",\n        )\n        print(f\"  已写出 : {args.json}\")\n\n    # 7.6 质量报告\n    print_quality_report(records, len(all_records), dup, total_font_entities)\n\n    print(f\"  下一步 : python build_ranking.py   （成员3 建模排序，产出 Top100）\\n\")\n    return 0\n\n\nif __name__ == \"__main__\":\n    force_utf8_console()          # 必须在任何 print 之前调用\n    try:\n        sys.exit(main())\n    except KeyboardInterrupt:\n        print(\"\\n已被手动中断（Ctrl+C）。\")\n        sys.exit(130)\n"}, "ranking": {"name": "build_ranking.py", "lines": 745, "src": "# -*- coding: utf-8 -*-\n\"\"\"\nbuild_ranking.py —— 按自定义评分口径产出「北京餐厅 Top100」榜单（成员3）\n================================================================================\n\n【它在流水线的位置】\n    成员1 采集 ──► 成员2 解析 ──► 【成员3 建模】──► 成员4 可视化\n    raw/*.html     restaurants_clean.csv        top100.csv    dashboard\n\n【这个脚本做什么】\n    把成员2 交付的干净数据 data/restaurants_clean.csv（150 家 × 8 字段），\n    按 config/scoring.yaml 里的口径算分、排序、去重，产出前三名榜单。\n\n    一条链：\n        读 CSV → 门槛过滤 → 归一化 → 加权算分 → 排序 → 品牌去重 → 取 Top100\n\n【核心公式】\n    final_score = w_rating × n(评分) + w_review × n(log(1 + 评论数))\n    n() 是把原始值压缩到 [0,1] 的归一化函数。\n\n【输入输出】\n    输入：data/restaurants_clean.csv      （成员2 产出，150 家 × 8 字段）\n          config/scoring.yaml             （评分口径：权重 / 归一化 / 筛选）\n          config/cuisine_map.yaml         （菜系归类：58 种细分品类 → 9 个菜系大类）\n    输出：data/top100.csv                 （主交付物，含分数分量与 cuisine 标签）\n          data/top100.json                （给成员4 前端读，数字是真数字类型）\n          data/dianping.db                （SQLite，含 ranking 表 + meta 口径快照）\n\n【关于 cuisine 字段】\n    category 是大众点评的原始细分品类（58 种：云南菜|滇菜、打边炉/港式火锅…），\n    cuisine 是本项目归并出的菜系大类（中餐/火锅/烧烤烤肉/西餐/日韩料理/\n    东南亚菜/自助餐/简餐烘焙/其他）。两列都保留：\n    要精确检索用 category，要分组统计、画饼图、看板筛选用 cuisine。\n    注意 cuisine 只是**标签**，不参与打分，榜单口径不受它影响。\n\n【为什么零第三方依赖】\n    和前两位成员保持一致：只用一个 Python 自带的标准库\n    （csv / json / math / sqlite3 / argparse / re / pathlib），\n    连 YAML 都是自己解析一个最简子集，所以队友下载下来直接能跑，不用 pip install。\n\n【运行】\n    python build_ranking.py                     # 按配置出榜\n    python build_ranking.py --compare           # 口径对比实验\n    python build_ranking.py --top 50            # 临时改榜单长度\n    python build_ranking.py --config other.yaml # 换一份口径\n\"\"\"\n\nimport argparse\nimport csv\nimport json\nimport math\nimport re\nimport sqlite3\nimport sys\nimport unicodedata\nfrom collections import Counter\nfrom datetime import datetime\nfrom pathlib import Path\n\n# __file__ 是本文件路径，parent 就是项目根目录（build_ranking.py 在根目录下）\nROOT = Path(__file__).resolve().parent\nDEFAULT_CONFIG = ROOT / \"config\" / \"scoring.yaml\"\nDEFAULT_CUISINE_MAP = ROOT / \"config\" / \"cuisine_map.yaml\"\nDEFAULT_SOURCE = ROOT / \"data\" / \"restaurants_clean.csv\"\n\n\n# =============================================================================\n# 第 1 部分：极简 YAML 读取\n# -----------------------------------------------------------------------------\n# 为什么要自己写？\n#   项目从成员1 开始就坚持\"零第三方依赖\"（crawler.py 只用标准库）。\n#   pyyaml 要 pip install，为了一个 30 行的配置文件引入一个依赖不划算。\n#   而 scoring.yaml 只用到「键: 值」和「两空格缩进」两种语法，写一个 40 行的解析器\n#   比装依赖更快，也更容易讲清楚。\n#\n# 支持的语法（够用即可，不追求完整 YAML）：\n#   key: value            → 标量\n#   key:                  → 嵌套字典，靠缩进确定层级\n#     sub: value\n#   # 注释                → 整行或行尾都行\n# =============================================================================\n\ndef _auto_type(text: str):\n    \"\"\"把 '0.625' 转成 float、'2000' 转成 int、'true' 转成 True，其余保留字符串。\"\"\"\n    text = text.strip().strip('\"').strip(\"'\")\n    if text == \"\":\n        return None\n    low = text.lower()\n    if low in (\"true\", \"yes\", \"on\"):\n        return True\n    if low in (\"false\", \"no\", \"off\"):\n        return False\n    if low in (\"null\", \"none\", \"~\"):\n        return None\n    try:\n        return int(text)\n    except ValueError:\n        pass\n    try:\n        return float(text)\n    except ValueError:\n        return text\n\n\ndef load_config(path: Path) -> dict:\n    \"\"\"解析最简 YAML。用 (缩进, 节点) 的栈来跟踪当前父节点。\"\"\"\n    if not path.exists():\n        raise SystemExit(f\"[X] 找不到配置文件：{path}\")\n\n    root: dict = {}\n    stack: list[tuple[int, dict]] = [(-1, root)]      # 根节点缩进记作 -1\n\n    for line_no, raw in enumerate(path.read_text(encoding=\"utf-8\").splitlines(), 1):\n        line = raw.split(\"#\", 1)[0].rstrip()          # 去掉行尾注释\n        if not line.strip():\n            continue\n\n        indent = len(line) - len(line.lstrip(\" \"))\n        key, sep, value = line.strip().partition(\":\")\n        if not sep:\n            raise SystemExit(f\"[X] {path.name} 第 {line_no} 行格式不对（缺少冒号）：{raw.strip()}\")\n\n        # 缩进变浅 → 弹栈，回到正确的父节点\n        while len(stack) > 1 and indent <= stack[-1][0]:\n            stack.pop()\n\n        parent = stack[-1][1]\n        if value.strip() == \"\":\n            node: dict = {}\n            parent[key.strip()] = node\n            stack.append((indent, node))              # 后面缩进更深的行归它管\n        else:\n            parent[key.strip()] = _auto_type(value)\n\n    return root\n\n\ndef normalize_config(raw: dict) -> dict:\n    \"\"\"\n    给配置补默认值，并把类型收紧。\n\n    这一步是防御性设计：配置文件是给人手改的，手改就会写错。\n    与其让错误在后面变成\"算出来一个奇怪的榜单\"，不如在入口就校验。\n    \"\"\"\n    weights = raw.get(\"weights\") or {}\n    if not weights:\n        raise SystemExit(\"[X] 配置里缺少 weights 段\")\n\n    known = {\"rating\", \"review_count\"}\n    unknown = set(weights) - known\n    if unknown:\n        raise SystemExit(f\"[X] weights 里有未知维度：{sorted(unknown)}，只支持 {sorted(known)}\")\n\n    weights = {k: float(v) for k, v in weights.items()}\n\n    # ⭐ 权重校验：两项必须合计 1.0。\n    #   这是本脚本最重要的一道防线——手改权重时少写 0.025，榜单会整体偏移但不会报错，\n    #   这种\"静默错误\"最难解释。\n    total = sum(weights.values())\n    if abs(total - 1.0) > 1e-9:\n        raise SystemExit(\n            f\"[X] 权重合计必须等于 1.0，当前是 {total:.6f}\\n\"\n            f\"    当前配置：{weights}\\n\"\n            f\"    提示：删除客流量维度后，正确口径是 0.625 / 0.375（按原 5:3 等比重分配）\"\n        )\n    if any(w < 0 or w > 1 for w in weights.values()):\n        raise SystemExit(f\"[X] 权重必须在 0~1 之间，当前：{weights}\")\n\n    norm = raw.get(\"normalize\") or {}\n    filt = raw.get(\"filter\") or {}\n    out = raw.get(\"output\") or {}\n\n    for dim, method in norm.items():\n        if dim in known and str(method) not in (\"minmax\", \"rank\"):\n            raise SystemExit(f\"[X] normalize.{dim} 只支持 minmax / rank，当前：{method}\")\n\n    return {\n        \"weights\": weights,\n        \"normalize\": {\n            \"rating\": str(norm.get(\"rating\", \"minmax\")),\n            \"review_count\": str(norm.get(\"review_count\", \"minmax\")),\n            \"log1p_review_count\": bool(norm.get(\"log1p_review_count\", True)),\n        },\n        \"filter\": {\n            \"min_review_count\": int(filt.get(\"min_review_count\", 0) or 0),\n            \"max_per_brand\": int(filt.get(\"max_per_brand\", 0) or 0),   # 0 = 不限\n        },\n        \"output\": {\"top_n\": int(out.get(\"top_n\", 100) or 100)},\n    }\n\n\n# =============================================================================\n# 第 2 部分：读数据 + 字段类型转换\n# -----------------------------------------------------------------------------\n# CSV 读出来全是字符串（'4.5'、'42277'），必须转成数字，\n# 否则排序会变成字符串比较：'9' > '10'，榜单直接错乱。\n# =============================================================================\n\ndef load_rows(path: Path) -> list[dict]:\n    if not path.exists():\n        raise SystemExit(f\"[X] 找不到数据文件：{path}\\n    请先确认成员2 的交付物已就位\")\n\n    with path.open(\"r\", encoding=\"utf-8-sig\", newline=\"\") as f:\n        rows = list(csv.DictReader(f))\n\n    if not rows:\n        raise SystemExit(f\"[X] {path.name} 是空的\")\n\n    required = {\"shop_id\", \"name\", \"rating\", \"review_count\", \"avg_price\", \"category\", \"district\"}\n    missing = required - set(rows[0].keys())\n    if missing:\n        raise SystemExit(f\"[X] 数据缺少字段：{sorted(missing)}\\n    当前字段：{list(rows[0].keys())}\")\n\n    for row in rows:\n        row[\"rating\"] = float(row[\"rating\"])\n        row[\"review_count\"] = int(float(row[\"review_count\"]))\n        row[\"avg_price\"] = int(float(row.get(\"avg_price\") or 0))\n        row[\"source_page\"] = int(float(row.get(\"source_page\") or 0))\n        # 品牌名：去掉括号里的分店信息，「四季民福烤鸭店(故宫店)」→「四季民福烤鸭店」\n        # 用于\"每品牌最多 N 家\"的去重，不改动原始店名\n        row[\"brand\"] = re.split(r\"[（(]\", row[\"name\"])[0].strip()\n\n    return rows\n\n\n# =============================================================================\n# 第 3 部分：菜系归类（把 58 种细分品类压成 9 个菜系大类）\n# -----------------------------------------------------------------------------\n# 为什么要做这件事：\n#   大众点评的 category 细到 58 种（「云南菜|滇菜」「打边炉/港式火锅」「日式烧烤/烤肉」），\n#   直接拿去画饼图会碎成 58 块，看不出任何结构。所以再加一层\"菜系大类\"：\n#       category（58 种，细，保留原值） → cuisine（9 类，粗，用于聚合）\n#   两列都留在输出里：想精确检索用 category，想分组统计/看板筛选用 cuisine。\n#\n# 规则放在 config/cuisine_map.yaml，按文件里的先后顺序匹配、命中即停，\n# 这样\"日式火锅归火锅\"这种判断是配置问题，不是代码问题——改口径不用改代码。\n# =============================================================================\n\ndef load_cuisine_rules(path: Path) -> list[tuple[str, list[str]]]:\n    \"\"\"\n    读出「菜系大类 → 关键词列表」，并保留文件里的顺序（顺序 = 匹配优先级）。\n\n    注意：这里复用第 1 部分的简易 YAML 解析器，所以格式被限定成\n        <菜系名>: 关键词1 关键词2 关键词3\n    一行一个菜系，关键词用空格分隔（不能用逗号，否则整串会被当成一个词）。\n    \"\"\"\n    if not path.exists():\n        raise SystemExit(\n            f\"[X] 找不到菜系规则文件：{path}\\n\"\n            f\"    这个文件决定 category → cuisine 的归类，缺失会导致输出没有菜系列\"\n        )\n\n    raw = load_config(path)\n    rules: list[tuple[str, list[str]]] = []\n    for family, keywords in raw.items():\n        if not isinstance(keywords, str):\n            raise SystemExit(f\"[X] cuisine_map.yaml 里的「{family}」必须是「关键词1 关键词2」这种一行写法\")\n        words = [w for w in keywords.split() if w]\n        if not words:\n            raise SystemExit(f\"[X] cuisine_map.yaml 里的「{family}」没有关键词\")\n        rules.append((family, words))\n\n    if not rules:\n        raise SystemExit(f\"[X] {path.name} 里没有任何归类规则\")\n    return rules\n\n\ndef classify_cuisine(category: str, rules: list[tuple[str, list[str]]]) -> str:\n    \"\"\"\n    把原始品类归到菜系大类，匹配不到就返回「其他」。\n\n    为什么用\"包含\"而不是\"等于\"？\n      因为原始品类带分隔符和修饰词——「云南菜|滇菜」要能命中\"云南菜\"，\n      「酸菜鱼/水煮鱼」要能命中\"酸菜鱼\"，「日式烧烤/烤肉」要能命中\"日式\"。\n      包含匹配对这类脏值最省事。\n    \"\"\"\n    text = category or \"\"\n    for family, keywords in rules:\n        for keyword in keywords:\n            if keyword in text:\n                return family\n    return \"其他\"\n\n\ndef attach_cuisine(rows: list[dict], rules: list[tuple[str, list[str]]]) -> list[str]:\n    \"\"\"给每条记录挂上 cuisine 字段，返回没归进任何规则的原始品类（用于自检）。\"\"\"\n    for row in rows:\n        row[\"cuisine\"] = classify_cuisine(row[\"category\"], rules)\n    return sorted({r[\"category\"] for r in rows if r[\"cuisine\"] == \"其他\"})\n\n\n# =============================================================================\n# 第 4 部分：归一化\n# -----------------------------------------------------------------------------\n# 两个维度量纲完全不同（评分 3.5~5.0，评论数 1384~77275），\n# 不归一化直接加权，评论数会把评分彻底吃掉。所以必须先压到同一把尺子上。\n# =============================================================================\n\ndef minmax(values: list[float]) -> list[float]:\n    lo, hi = min(values), max(values)\n    if hi == lo:                                   # 全部相同 → 都取中性值 0.5，避免除零\n        return [0.5] * len(values)\n    return [(v - lo) / (hi - lo) for v in values]\n\n\ndef rank_norm(values: list[float]) -> list[float]:\n    \"\"\"分位数归一化：把原始值换成分位排名，相同的值取平均名次（保证并列者同分）。\"\"\"\n    n = len(values)\n    order = sorted(range(n), key=lambda i: values[i])\n    result = [0.0] * n\n    i = 0\n    while i < n:\n        j = i\n        while j + 1 < n and values[order[j + 1]] == values[order[i]]:\n            j += 1\n        share = (i + j) / 2 / max(n - 1, 1)        # 并列者共用平均名次\n        for k in range(i, j + 1):\n            result[order[k]] = share\n        i = j + 1\n    return result\n\n\ndef _raw_dimension(rows: list[dict], dim: str, cfg: dict) -> list[float]:\n    \"\"\"取某维度的原始值。评论数按配置先做 log1p 变换。\"\"\"\n    if dim == \"review_count\" and cfg[\"normalize\"][\"log1p_review_count\"]:\n        return [math.log1p(r[\"review_count\"]) for r in rows]\n    return [float(r[dim]) for r in rows]\n\n\n# =============================================================================\n# 第 5 部分：加权打分\n# =============================================================================\n\ndef score_rows(rows: list[dict], cfg: dict) -> list[dict]:\n    \"\"\"给每条记录算 final_score，并把两个归一化分量一起带回（便于报告和前端画图）。\"\"\"\n    normed: dict[str, list[float]] = {}\n    for dim in cfg[\"weights\"]:\n        values = _raw_dimension(rows, dim, cfg)\n        method = cfg[\"normalize\"].get(dim, \"minmax\")\n        normed[dim] = rank_norm(values) if method == \"rank\" else minmax(values)\n\n    scored = []\n    for i, row in enumerate(rows):\n        record = dict(row)\n        record[\"rating_norm\"] = round(normed[\"rating\"][i], 6)\n        record[\"review_norm\"] = round(normed[\"review_count\"][i], 6)\n        total = 0.0\n        for dim, weight in cfg[\"weights\"].items():\n            total += weight * normed[dim][i]\n        record[\"final_score\"] = round(total, 6)\n        scored.append(record)\n    return scored\n\n\n# =============================================================================\n# 第 6 部分：排序、品牌去重、定榜\n# -----------------------------------------------------------------------------\n# 排序键是一个元组，按优先级从左到右比较：\n#   ① final_score 降序      —— 主口径\n#   ② rating 降序           —— 同分时\"评分高者优先\"：评分区分度低，但语义上更重要\n#   ③ review_count 降序     —— 再同分就比人气\n#   ④ name 升序             —— 最后的确定性兜底，保证任何人重跑结果完全一致\n#\n# 第 ④ 项看着多余，其实很关键：Python 的排序是稳定的，但如果输入顺序变了\n# （比如换了一台机器、成员2 重跑了 parser），同分店的先后就会变。\n# 加一个确定的兜底字段，榜单才是可复现的。\n# =============================================================================\n\ndef sort_key(record: dict):\n    return (-record[\"final_score\"], -record[\"rating\"], -record[\"review_count\"], record[\"name\"])\n\n\ndef dedupe_by_brand(sorted_rows: list[dict], cap: int, top_n: int) -> tuple[list[dict], int]:\n    \"\"\"按品牌限额取前 top_n 条。cap<=0 表示不限。返回 (榜单, 因品牌限额被剔除的条数)。\"\"\"\n    if cap <= 0:\n        return sorted_rows[:top_n], 0\n\n    picked: list[dict] = []\n    counter: Counter = Counter()\n    dropped = 0\n    for record in sorted_rows:\n        brand = record[\"brand\"]\n        if counter[brand] >= cap:\n            dropped += 1\n            continue\n        counter[brand] += 1\n        picked.append(record)\n        if len(picked) == top_n:\n            break\n    return picked, dropped\n\n\ndef build_ranking(rows: list[dict], cfg: dict) -> dict:\n    \"\"\"完整流水线：过滤 → 打分 → 排序 → 去重定榜。返回中间统计一起给报告用。\"\"\"\n    min_review = cfg[\"filter\"][\"min_review_count\"]\n    kept = [r for r in rows if r[\"review_count\"] >= min_review]\n\n    if len(kept) < cfg[\"output\"][\"top_n\"]:\n        print(f\"[!] 门槛过滤后只剩 {len(kept)} 条，少于目标榜单长度 {cfg['output']['top_n']}\")\n        print(f\"    建议调低 filter.min_review_count（当前 {min_review}）\")\n\n    scored = score_rows(kept, cfg)\n    ordered = sorted(scored, key=sort_key)\n    top, dropped = dedupe_by_brand(ordered, cfg[\"filter\"][\"max_per_brand\"], cfg[\"output\"][\"top_n\"])\n\n    # 写入名次。名次表示\"榜单位置\"，不是\"分数排名\"——去重后名次是连续的 1..N\n    for position, record in enumerate(top, 1):\n        record[\"rank\"] = position\n\n    return {\n        \"top\": top,\n        \"stats\": {\n            \"input_total\": len(rows),\n            \"after_threshold\": len(kept),\n            \"threshold_removed\": len(rows) - len(kept),\n            \"brand_dropped\": dropped,\n            \"output_total\": len(top),\n        },\n    }\n\n\n# =============================================================================\n# 第 7 部分：三处输出（CSV / JSON / SQLite）\n# -----------------------------------------------------------------------------\n\nOUTPUT_FIELDS = [\n    \"rank\", \"shop_id\", \"name\", \"brand\",\n    \"category\", \"cuisine\",                    # category = 原始细分品类（58 种）\n                                              # cuisine  = 菜系大类（9 类，用于分组统计）\n    \"district\",\n    \"rating\", \"review_count\", \"avg_price\",\n    \"rating_norm\", \"review_norm\", \"final_score\", \"source_page\",\n]\n\n\ndef write_csv(top: list[dict], path: Path) -> None:\n    \"\"\"\n    两个细节（成员2 也踩过，这里保持一致）：\n      newline=\"\"      —— csv 模块的要求，否则 Windows 上每行之间多出空行\n      utf-8-sig       —— 带 BOM 的 UTF-8，双击用 Excel 打开中文不乱码\n    \"\"\"\n    path.parent.mkdir(parents=True, exist_ok=True)\n    with path.open(\"w\", newline=\"\", encoding=\"utf-8-sig\") as f:\n        writer = csv.DictWriter(f, fieldnames=OUTPUT_FIELDS, extrasaction=\"ignore\")\n        writer.writeheader()\n        writer.writerows(top)\n\n\ndef write_json(top: list[dict], path: Path, cfg: dict) -> None:\n    \"\"\"\n    给成员4 的前端用。关键点：数字字段必须是真数字，不能是字符串，\n    否则前端拿到 '0.9797' 没法比较大小、没法画图。\n    口径（weights / filter）一起写进去，方便看板标注\"数据口径\"。\n    \"\"\"\n    path.parent.mkdir(parents=True, exist_ok=True)\n    payload = {\n        \"generated_at\": datetime.now().isoformat(timespec=\"seconds\"),\n        \"source\": \"data/restaurants_clean.csv\",\n        \"count\": len(top),\n        \"config\": cfg,\n        \"items\": [{k: r[k] for k in OUTPUT_FIELDS} for r in top],\n    }\n    path.write_text(json.dumps(payload, ensure_ascii=False, indent=2), encoding=\"utf-8\")\n\n\nCUISINE_FULL_FIELDS = [\n    \"shop_id\", \"name\", \"brand\", \"category\", \"cuisine\", \"district\",\n    \"rating\", \"review_count\", \"avg_price\", \"source_page\",\n]\n\n\ndef write_cuisine_full(rows: list[dict], path: Path) -> None:\n    \"\"\"\n    全量导出：150 家都带上菜系标签，不做门槛筛选、不做品牌去重。\n\n    注意这是**新建文件**，不会改动成员2 的 data/restaurants_clean.csv——\n    那份文件\"重跑字节级一致\"是成员2 的验证结论，动它会毁掉这个结论。\n    \"\"\"\n    path.parent.mkdir(parents=True, exist_ok=True)\n    ordered = sorted(rows, key=lambda r: (-r[\"rating\"], -r[\"review_count\"]))\n    with path.open(\"w\", newline=\"\", encoding=\"utf-8-sig\") as f:\n        writer = csv.DictWriter(f, fieldnames=CUISINE_FULL_FIELDS, extrasaction=\"ignore\")\n        writer.writeheader()\n        writer.writerows(ordered)\n\n\ndef write_sqlite(top: list[dict], path: Path, cfg: dict) -> None:\n    \"\"\"落一个 SQLite 库，报告里\"结果持久化\"和\"可按任意维度复筛\"都能自圆其说。\"\"\"\n    path.parent.mkdir(parents=True, exist_ok=True)\n    conn = sqlite3.connect(path)\n    try:\n        conn.execute(\"DROP TABLE IF EXISTS ranking\")\n        conn.execute(\"DROP TABLE IF EXISTS meta\")\n        conn.execute(\n            \"\"\"\n            CREATE TABLE ranking (\n                rank        INTEGER PRIMARY KEY,\n                shop_id     TEXT,\n                name        TEXT,\n                brand       TEXT,\n                category    TEXT,\n                cuisine     TEXT,\n                district    TEXT,\n                rating      REAL,\n                review_count INTEGER,\n                avg_price   INTEGER,\n                rating_norm REAL,\n                review_norm REAL,\n                final_score REAL,\n                source_page INTEGER\n            )\n            \"\"\"\n        )\n        conn.executemany(\n            f\"INSERT INTO ranking ({','.join(OUTPUT_FIELDS)}) \"\n            f\"VALUES ({','.join('?' * len(OUTPUT_FIELDS))})\",\n            [tuple(r[k] for k in OUTPUT_FIELDS) for r in top],\n        )\n        # 索引：按分数查、按商圈筛都是报告里会用到的查询\n        conn.execute(\"CREATE INDEX idx_ranking_score ON ranking(final_score DESC)\")\n        conn.execute(\"CREATE INDEX idx_ranking_district ON ranking(district)\")\n        conn.execute(\"CREATE INDEX idx_ranking_cuisine ON ranking(cuisine)\")\n\n        # meta 表存口径快照 —— 保证\"这个榜单是哪套参数算出来的\"可追溯\n        conn.execute(\"CREATE TABLE meta (key TEXT PRIMARY KEY, value TEXT)\")\n        conn.executemany(\n            \"INSERT INTO meta (key, value) VALUES (?, ?)\",\n            [\n                (\"generated_at\", datetime.now().isoformat(timespec=\"seconds\")),\n                (\"weights\", json.dumps(cfg[\"weights\"], ensure_ascii=False)),\n                (\"normalize\", json.dumps(cfg[\"normalize\"], ensure_ascii=False)),\n                (\"filter\", json.dumps(cfg[\"filter\"], ensure_ascii=False)),\n                (\"count\", str(len(top))),\n            ],\n        )\n        conn.commit()\n    finally:\n        conn.close()\n\n\n# =============================================================================\n# 第 8 部分：控制台报告\n# -----------------------------------------------------------------------------\n# 这一段是\"体检报告\"，也是成员3 这部分的主要产出：\n# 不只输出榜单，还要说明榜单是怎么被塑形的。\n# =============================================================================\n\ndef _width(text) -> int:\n    \"\"\"中日韩字符占两列，用它算显示宽度，避免表格错位。\"\"\"\n    return sum(2 if unicodedata.east_asian_width(ch) in \"WF\" else 1 for ch in str(text))\n\n\ndef _pad(text, width: int) -> str:\n    text = str(text)\n    return text + \" \" * max(0, width - _width(text))\n\n\ndef print_report(result: dict, top: list[dict]) -> None:\n    stats = result[\"stats\"]\n    line = \"=\" * 74\n\n    print(\"\\n\" + line)\n    print(\"  榜单生成报告\")\n    print(line)\n    print(f\"  输入数据     : restaurants_clean.csv  {stats['input_total']} 家\")\n    print(f\"  门槛过滤     : 评论数门槛剔除 {stats['threshold_removed']} 家\"\n          f\" → 剩余 {stats['after_threshold']} 家\")\n    if result[\"stats\"][\"brand_dropped\"]:\n        print(f\"  品牌去重     : 因品牌限额再剔除 {stats['brand_dropped']} 家\")\n    print(f\"  最终榜单     : Top {stats['output_total']}\")\n\n    print(\"-\" * 74)\n    # 榜单结构：这几行是最有说服力的数字\n    full_rating = sum(1 for r in top if r[\"rating\"] == 5.0)\n    brands = len(set(r[\"brand\"] for r in top))\n    dup_rate = (1 - brands / len(top)) * 100\n    print(f\"  覆盖品牌     : {brands} 个\"\n          f\"（品牌重复率 {dup_rate:.0f}% ，即 {'0' if dup_rate < 1 else int(len(top) - brands)} 个榜位被同品牌门店占用）\")\n    print(f\"  覆盖品类     : {len(set(r['category'] for r in top))} 个（原始细分品类）\")\n    print(f\"  覆盖菜系     : {len(set(r['cuisine'] for r in top))} 个（大类）\")\n    print(f\"  满分门店     : {full_rating} 家 / {len(top)}（{full_rating / len(top) * 100:.1f}%）\")\n    rng = [r[\"review_count\"] for r in top]\n    print(f\"  评论数区间   : {min(rng):,} ~ {max(rng):,}\")\n    print(f\"  分数区间     : {min(r['final_score'] for r in top):.4f} ~ \"\n          f\"{max(r['final_score'] for r in top):.4f}\")\n\n    print(\"-\" * 74)\n    print(\"  菜系分布：\")\n    counts = Counter(r[\"cuisine\"] for r in top)\n    top_count = max(counts.values())\n    for cuisine, count in counts.most_common():\n        bar = \"#\" * max(1, round(count / top_count * 28))     # 用最长的菜系做满格\n        print(f\"    {_pad(cuisine, 12)}{count:>3} 家  {count / len(top) * 100:>5.1f}%  {bar}\")\n\n    print(\"-\" * 74)\n    print(\"  Top 10 预览：\")\n    for record in top[:10]:\n        print(f\"   {record['rank']:>3}. {_pad(record['name'], 34)}\"\n              f\"{record['rating']:.1f}分  {record['review_count']:>6,}条  \"\n              f\"¥{record['avg_price']:<5} {record['final_score']:.4f}\")\n    print(line + \"\\n\")\n\n\n# =============================================================================\n# 第 9 部分：口径对比实验（--compare）\n# -----------------------------------------------------------------------------\n# 用途：演示\"为什么最终选这套口径\"。\n# 不写死结论，而是把几种候选口径都跑一遍，用重合度说明差异有多大。\n# 这正是报告里\"方法论严谨\"的证据：口径是被比较后选出来的，不是拍脑袋定的。\n# =============================================================================\n\ndef compare_variants(rows: list[dict], base_cfg: dict) -> None:\n    \"\"\"\n    第一行是**当前生效口径**（直接读 config/scoring.yaml），后面每行只改一个变量，\n    其余参数保持不变，所以\"差异几家\"这个数可以干净地归因到那一个改动上。\n    \"\"\"\n    cur_w = base_cfg[\"weights\"]\n    cur_cap = base_cfg[\"filter\"][\"max_per_brand\"]\n    cur_norm = base_cfg[\"normalize\"][\"rating\"]\n\n    variants = [\n        (f\"当前口径 {cur_w['rating']:g}/{cur_w['review_count']:g} 限{cur_cap or '不限'}家\",\n         cur_w, cur_cap, cur_norm),\n        (\"　　只去掉品牌限额\",        cur_w, 0, cur_norm),\n        (\"　　品牌限额放宽到 2 家\",  cur_w, 2, cur_norm),\n        (\"　　权重改 0.50 / 0.50\",   {\"rating\": 0.50, \"review_count\": 0.50}, cur_cap, cur_norm),\n        (\"　　权重改 0.40 / 0.60\",   {\"rating\": 0.40, \"review_count\": 0.60}, cur_cap, cur_norm),\n        (\"　　评分改 rank 归一化\",   cur_w, cur_cap, \"rank\"),\n    ]\n\n    print(\"\\n\" + \"=\" * 78)\n    print(\"  口径对比实验（第一行是当前口径，下面每行只改一个变量）\")\n    print(\"=\" * 78)\n    header = (f\"  {_pad('方案', 30)}{_pad('品牌', 6)}{_pad('满分店', 8)}\"\n              f\"{_pad('重合', 8)}{_pad('换人', 8)}\")\n    print(header)\n    print(\"-\" * 78)\n\n    baseline_ids: set[str] | None = None\n    for label, weights, cap, rating_norm in variants:\n        cfg = {\n            \"weights\": {k: round(float(v), 6) for k, v in weights.items()},\n            \"normalize\": {**base_cfg[\"normalize\"], \"rating\": rating_norm},\n            \"filter\": {**base_cfg[\"filter\"], \"max_per_brand\": cap},\n            \"output\": base_cfg[\"output\"],\n        }\n        result = build_ranking(rows, cfg)\n        top = result[\"top\"]\n        ids = {r[\"shop_id\"] for r in top}\n        if baseline_ids is None:\n            baseline_ids = ids\n            overlap, changed = \"—\", \"—\"\n        else:\n            overlap = f\"{len(ids & baseline_ids)}\"\n            changed = f\"{len(ids ^ baseline_ids) // 2}\"     # 对称差的一半 = 换进/换出的家数\n\n        brand_count = len(set(r[\"brand\"] for r in top))\n        full_count = sum(1 for r in top if r[\"rating\"] == 5.0)\n        print(f\"  {_pad(label, 30)}{_pad(brand_count, 6)}{_pad(full_count, 8)}\"\n              f\"{_pad(overlap, 8)}{_pad(changed, 8)}\")\n\n    print(\"-\" * 78)\n    print(\"  读法：重合 = 与当前口径相比仍在榜内的家数；换人 = 换进了几家、同时换出了几家。\")\n    print(\"        换人 ≤ 4 说明这个改动对榜单几乎无影响，不值得为它增加解释成本；\")\n    print(\"        品牌数从 85 涨到 100 说明榜单多样性提升，这是可写进报告的改进。\")\n    print(\"=\" * 78 + \"\\n\")\n\n\n# =============================================================================\n# 第 10 部分：主流程\n# =============================================================================\n\ndef main() -> int:\n    parser = argparse.ArgumentParser(description=\"按自定义评分口径产出 Top100 榜单\")\n    parser.add_argument(\"--config\", default=str(DEFAULT_CONFIG), help=\"口径配置文件\")\n    parser.add_argument(\"--cuisine-map\", default=str(DEFAULT_CUISINE_MAP), help=\"菜系归类规则\")\n    parser.add_argument(\"--source\", default=str(DEFAULT_SOURCE), help=\"输入 CSV\")\n    parser.add_argument(\"--out-dir\", default=str(ROOT / \"data\"), help=\"输出目录\")\n    parser.add_argument(\"--top\", type=int, default=0, help=\"临时覆盖榜单长度\")\n    parser.add_argument(\"--compare\", action=\"store_true\", help=\"只跑口径对比实验，不写文件\")\n    parser.add_argument(\"--export-all\", action=\"store_true\",\n                        help=\"额外输出 data/cuisine_full.csv（全部 150 家的菜系标签，不做筛选）\")\n    args = parser.parse_args()\n\n    # 10.1 读配置并校验（权重合计必须是 1.0）\n    cfg = normalize_config(load_config(Path(args.config)))\n    if args.top > 0:\n        cfg[\"output\"][\"top_n\"] = args.top\n\n    # 10.2 读数据 + 挂菜系标签\n    rows = load_rows(Path(args.source))\n    rules = load_cuisine_rules(Path(args.cuisine_map))\n    unmatched = attach_cuisine(rows, rules)\n    print(f\"[1/5] 读入 {len(rows)} 家门店 ← {Path(args.source).name}\")\n    if unmatched:\n        print(f\"      菜系归类 {len(rules)} 条规则；有 {len(unmatched)} 种原始品类未命中规则，\"\n              f\"归入「其他」：{unmatched}\")\n    else:\n        print(f\"      菜系归类 {len(rules)} 条规则，全部品类均命中\")\n\n    # 10.3 口径对比（可选，不落盘）\n    if args.compare:\n        compare_variants(rows, cfg)\n        return 0\n\n    # 10.4 建模\n    print(f\"[2/5] 权重 {cfg['weights']}（合计 {sum(cfg['weights'].values()):.3f} 校验通过）\")\n    print(f\"      归一化 rating={cfg['normalize']['rating']} \"\n          f\"review_count={cfg['normalize']['review_count']}\"\n          + (\"（已 log1p）\" if cfg['normalize']['log1p_review_count'] else \"\"))\n    print(f\"[3/5] 门槛 评论数≥{cfg['filter']['min_review_count']}，\"\n          f\"每品牌上限 {cfg['filter']['max_per_brand'] or '不限'}\")\n    result = build_ranking(rows, cfg)\n    top = result[\"top\"]\n\n    # 10.5 三处输出\n    out_dir = Path(args.out_dir)\n    write_csv(top, out_dir / \"top100.csv\")\n    write_json(top, out_dir / \"top100.json\", cfg)\n    write_sqlite(top, out_dir / \"dianping.db\", cfg)\n    print(f\"[4/5] 已写出 → data/top100.csv / data/top100.json / data/dianping.db\")\n\n    # 全量导出（可选）：把 150 家的菜系标签也落一份，方便成员4 做全量分布分析。\n    # 注意它是**新文件**，不改动成员2 的 restaurants_clean.csv——\n    # 那份文件的可复现性（字节级 SHA 一致）是成员2 的验证结论，不能被动。\n    if args.export_all:\n        write_cuisine_full(rows, out_dir / \"cuisine_full.csv\")\n        print(f\"      另存全量 → data/cuisine_full.csv（{len(rows)} 家，含 cuisine 标签）\")\n\n    # 10.6 报告\n    print(\"[5/5] 完成\")\n    print_report(result, top)\n    print(\"  下一步：\")\n    print(\"    python tools/sync_dashboard_data.py   （把榜单同步成看板可读的 top100.json）\")\n    print(\"    python build_ranking.py --compare     （看不同口径的榜单差异）\\n\")\n    return 0\n\n\nif __name__ == \"__main__\":\n    # 中文版 Windows 的控制台默认 GBK，这里切 UTF-8，否则打印中文和 emoji 会报错\n    try:\n        sys.stdout.reconfigure(encoding=\"utf-8\", errors=\"replace\")\n    except Exception:                              # noqa: BLE001 —— 改不了也照常跑\n        pass\n    raise SystemExit(main())\n"}};
